import hashlib, math

class HyperLogLog:
    def __init__(self, p: int = 12):
        if not (4 <= p <= 18):
            raise ValueError('p must be between 4 and 18')
        self.p = p
        self.m = 1 << p
        self.regs = bytearray(self.m)
        self.alpha = 0.7213 / (1.0 + 1.079 / self.m)

def add(self, item: str) -> None:
        h = int.from_bytes(hashlib.blake2b(item.encode(), digest_size=8).digest(), 'big')
        idx = h >> (64 - self.p)
        tail = ((h << self.p) & ((1 << 64) - 1)) | (1 << (self.p - 1))
        rho = (64 - self.p) - tail.bit_length() + 1
        if rho > self.regs[idx]:
            self.regs[idx] = rho

def merge(self, other: 'HyperLogLog') -> None:
        if self.p != other.p:
            raise ValueError('Cannot merge HLLs with different precision p')
        for i in range(self.m):
            if other.regs[i] > self.regs[i]:
                self.regs[i] = other.regs[i]

